I'm writing a test using testClient from Hono. I expect the Authorization header to be received in the request handler, but it appears to be missing or not matching. Here's the code:

## index.ts
```index.ts
import { Hono, type Context } from "hono";

const app = new Hono().get("/", (c: Context) => {
  const authorizationHeader = c.req.header("Authorization");
  console.log(authorizationHeader);

  if (!authorizationHeader && authorizationHeader !== "123") {
    return c.text("not complete", 500);
  }

  return c.text("complete", 200);
});

export default app;

```
## index.spec.ts
```index.spec.ts
import { describe, expect, it } from "bun:test";
import { testClient } from "hono/testing";
import app from "./index";

describe("Sandbox", () => {
  const client = testClient(app);

  it("should return 200", async () => {
    const response = await client.index.$get({
      headers: {
        Authorization: "123",
